import json, math, resource, time, hashlib, html, platform
from pathlib import Path
from datetime import datetime, timezone
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from science import R, load, dump, sha, csvout, SEGS, GUIDES
NAMES = {'fully_guided': 'Fullt guidat', 'pilot_guided': 'Pilotguidat', 'freehand': 'Frihand', 'dynamic_navigation': 'Dynamisk navigation'}
SEGNAME = {SEGS[0]: 'Mentalproxy*', SEGS[1]: 'Molarregion', SEGS[2]: 'Posterior grenproxy*'}

def fmt(x, d=2):
    return f'{x:.{d}f}' if isinstance(x, (int, float)) else 'UNKNOWN'

def main():
    start = time.perf_counter()
    r1 = load('raw/R1_RESULT.json')
    r2 = load('raw/R2_RESULT.json')
    r3 = load('raw/R3_RESULT.json')
    r4 = load('raw/R4_RESULT.json')
    val = load('raw/VALIDATION.json')
    sc = load('raw/SOURCE_CONTROLS.json')
    external = load('raw/EXTERNAL_COMPARISON.json')
    sites = load('inputs/lineage_sites.json')
    lookup = {(r['guide'], r['segment'], r['target']): r for r in r4['tables']}
    table = ['| Guide | Segment | Error budget 90 % mm | Error budget 95 % mm | Modified / 100 , 90 % | Modified / 100 , 95 % | Empirical physical coverage |', '|---|---|---:|---:|---:|---:|---|']
    printable = []
    for gid in GUIDES:
        for seg in SEGS:
            (a, b) = (lookup[gid, seg, 0.9], lookup[gid, seg, 0.95])
            mark = ' †' if seg == SEGS[0] else ''
            table.append(f"| {NAMES[gid]} | {SEGNAME[seg]} | {fmt(a['margin_mm'])}{mark} | {fmt(b['margin_mm'])}{mark} | {fmt(a['changes_per100'], 1)} | {fmt(b['changes_per100'], 1)} | UNKNOWN |")
            printable.append({'guide': NAMES[gid], 'segment': SEGNAME[seg], 'budget90_mm': a['margin_mm'], 'budget95_mm': b['margin_mm'], 'changes90_per100': a['changes_per100'], 'changes95_per100': b['changes_per100'], 'physical_coverage': 'UNKNOWN', 'resolution': 'PHENOMENOLOGICAL', 'count_resolution': 'POPULATION'})
    csvout('tables/NERVE_MARGIN_TABLE.csv', printable)
    rev = ['| Segment | Audit objectives | Budget mm | Covered image groups | Noted coverage [95 %KI ] | Frozen gate |', '|---|---:|---:|---:|---|']
    for v in r4['revision_validation']:
        cv = v['heldout_coverage']
        (lo, hi) = v['ci95']
        band = f'{100 * cv:.1f} % [{100 * lo:.1f}–{100 * hi:.1f}]' if cv is not None else '—'
        rev.append(f"| {SEGNAME[v['segment']]} | {100 * v['revision_target']:g} % | {fmt(v['budget_mm'])} | {v['covered']}/{v['heldout_n']} | {band} | {v['heldout_gate']} |")
    local = ['| Guide | Mentalproxy, 90/95 % median [min–max] mm | Molar, 90/95 % median [min–max] mm |', '|---|---|---|']
    for gid in GUIDES:
        cols = []
        for seg in SEGS[:2]:
            vals = []
            for target in [0.9, 0.95]:
                r = next((x for x in r3['tables'] if (x['guide'], x['segment'], x['target']) == (gid, seg, target)))
                vals.append(f"{fmt(r['margin_mm'])} [{fmt(r['margin_min_mm'])}–{fmt(r['margin_max_mm'])}]")
            cols.append(' / '.join(vals))
        local.append(f'| {NAMES[gid]} | {cols[0]} | {cols[1]} |')
    plt.rcParams.update({'font.size': 10, 'font.family': 'DejaVu Sans'})
    (fig, axes) = plt.subplots(1, 3, figsize=(15, 6), gridspec_kw={'width_ratios': [1, 1, 1.15]})
    y = np.arange(4)
    for (ax, seg) in zip(axes[:2], SEGS[:2]):
        for (target, off, col) in [(0.9, -0.16, '#397cb5'), (0.95, 0.16, '#c67c26')]:
            vv = [lookup[g, seg, target]['margin_mm'] for g in GUIDES]
            bars = ax.barh(y + off, vv, height=0.28, color=col, label=f'{100 * target:g} % Model Target')
            for (bar, v) in zip(bars, vv):
                ax.text(v + 0.12, bar.get_y() + bar.get_height() / 2, f'{v:.2f}', va='center', fontsize=9)
        ax.axvline(2, color='black', ls='--', lw=1, label='Fast 2 mm')
        ax.set_yticks(y)
        ax.set_yticklabels([NAMES[g] for g in GUIDES] if ax is axes[0] else [''] * 4)
        ax.invert_yaxis()
        ax.set_xlim(0, max((lookup[g, seg, 0.95]['margin_mm'] for g in GUIDES)) + 2)
        ax.set_xlabel('Clean error budget (mm ), no extra residual target')
        ax.set_title(SEGNAME[seg] + ('\nrevisionsgrind REJECTED' if seg == SEGS[0] else '\nAudit gate complete; physical coverage unknown'))
        ax.grid(axis='x', alpha=0.15)
    axes[0].legend(loc='lower right', fontsize=8)
    vv = [v for v in r4['revision_validation'] if v['segment'] in SEGS[:2]]
    ax = axes[2]
    for (i, v) in enumerate(vv):
        cv = v['heldout_coverage']
        (lo, hi) = v['ci95']
        col = '#397cb5' if v['target'] == 0.9 else '#c67c26'
        ax.errorbar(100 * cv, i, xerr=np.array([[100 * (cv - lo)], [100 * (hi - cv)]]), fmt='o', color=col, capsize=3)
        ax.plot(100 * v['revision_target'], i, '|', color='black', markersize=18)
        ax.text(70, i, f"{v['covered']}/{v['heldout_n']}", va='center', fontsize=8)
    ax.set_yticks(range(4))
    ax.set_yticklabels([SEGNAME[v['segment']] + f"\nkrav {100 * v['revision_target']:g} %" for v in vv], fontsize=9)
    ax.set_xlim(69, 100.5)
    ax.invert_yaxis()
    ax.set_xlabel('Observed audit coverage (%), exact binomial KI')
    ax.set_title('Discontinued image groups\nBlack mark = frozen audit target')
    ax.grid(axis='x', alpha=0.15)
    fig.suptitle('Nerve channel error budget: executable research model, physical 90 / 95 %- coverage UNKNOWN', fontsize=14)
    fig.text(0.04, 0.03, 'Rear branch: none matched queries. *Mentalproxy  No nerve injury risk is calculated.\nGuideprofilernas stickprovsmoment antas vara populationsmoment. Audits  PER_TOOTH → PHENOMENOLOGICAL.', fontsize=9)
    fig.tight_layout(rect=[0, 0.12, 1, 0.94])
    fig.savefig(R / 'figures/nerve_margin_table.png', dpi=170)
    fig.savefig(R / 'figures/nerve_margin_table.pdf')
    plt.close(fig)
    readme = "# Error budget for the nerve channel: research review table\n\nFour guide system can now be asked at 90/95 percentage targets with channel segments, location lines and decisions against fixed 2 mm. External reference verifies guide input data and distinguishes independent channel racing from local mask revisions. **A necessary clinical margin with empirical 90/95 %-coverage is still UNKNOWN in all twelve combinations.** The table is a executable research data, no clinical recommendation.\n\nThe idea: a planned digital distance must cover the implant's movement and loss when the channel's mask changes. We link published guide errors to the actual cylinder's targeted audit loss on the same image. The prize measure is changed virtual decisions compared to fixed 2 mm; no algorithm superior is claimed. This extends X73 : s 90 percentage scenario to both targets, explicit residual targets and site-bound corrections.\n\nRun from this directory: `./run_all.sh` . Existing system-Python with NumPy/SciPy/Matplotlib is used via `python3 -s` to avoid a local NumPy/Matplotlib conflict. A thread, no GPU, no network access or data set extraction during replay. CSV: [NERVE_MARGIN_TABLE.csv](tables/NERVE_MARGIN_TABLE.csv). Print: [PRINT_TABLE.html](PRINT_TABLE.html). [Figure PDF](figures/nerve_margin_table.pdf).\n\n## Result : guide × segment\n\n" + '\n'.join(table) + "\n\nEach mm - value is **PHENOMENOLOGICAL**: a conservative upper model budget, not a measured requirement or a minimal clinical margin. Here is the residual target **0 mm**, so the value only covers the modeled errors. Positive digital separation requires that the nominal gap **extly exceeds** budget. A separate residual target c is added: m(c)=c+guide budget+audit budget. Keeping 2 mm after errors just gives 2 mm bigger thresholds in the preserved [R2 -table](tables/R2_MARGINS.csv). No clinically acceptable residual limit is determined here.\n\n† Mentalproxy's audit gate fails at both targets: the numbers are shown to preserve the outcome and do not receive an empirical coverage label. *The frame mentale is only represented by X73 : s terminal 5 mm -proxy; the rear branch of its terminal 10 mm -proxy. Anatomical landmarks have not been validated. There are no queries in the rear branch, therefore no mm - values . The Molar region is the nearest FDI landmark to the active channel wall witness point.\n\nThe number in the table applies **unheld** image group+ FDI - sites : mental proxy 181 , molar 127 ( 184 / 130 poses). A site changes if any of its preserved poses go from ABOVE at 2 mm to BELOW at the model threshold. The denominator is all retained sites in the segment, even already BELOW at 2 mm . No number is clinical prevalence or nerve damage. Non-decision is PER_TOOTH, shares POPULATION. An alternative pose is retained in the [Grade Table](raw/R4_PER_POSE.csv).\n\n## What the coverage actually can do\n\nHalf the error budget is allocated to audit and half the guide error. For 90 % total, 95 % revision and 95 % guide are used; for 95 %, 97,5 % of each is used. The Union border does not require independent misdirections. The guide error is limited with one-sided Cantelli for entry, apex and angle, and G=max(entry,apex) +2 r · sin(θ/ 2 ), r ≤  2   mm . Published sample moments are treated as exact population moments: an unvalidated closure. No gamma, isotropi or extra Gaussian channeljitter is added.\n\n" + '\n'.join(rev) + "\n\nThe gates compare observed coverage with the pre-registered audit target. Even the molar region's PASS has wide KI and proves no population guarantee. Rang is ceil((n_cal +1 ) · goal ) on patient/image groupmax for frozen poses; too few groups give INF . Precise forms are held on the same side of the inherited 88/60 division. The guide error has not been observed in these patients and the line to the real canal wall is missing.\n\n## A useful location-bound correction\n\nR3 replaces the falsifiable regional revision quantile with each frozen poses measured loss to the Union of published masks. It removes the need for future patient exchangeability for **just the already observed digital union**. All 711 segment-bound poses are capable of the control range within 1e-10 mm ; in total there are 748 poses. The guide coverage is still conditional . The following is descriptive median [min –max], with residual target 2 mm ; the median is never used as threshold for a site :\n\n" + '\n'.join(local) + "\n\nBakre gren saknar rader. The minimum representation is the matched `(pose, wall witness, directed loss)` row. The holds medium, the entire loss distribution and the median/range exactly equal (identity error 0,0 ), but different linkages to the same gap give 50 percentage points difference in accepted sites . Keeping the same regional summary is not enough. [Receipt](raw/SUFFICIENCY_SITE_PAIRING.json) is your own logical fixture, no anatomic reference . A separate torque sample has identity error 0,0 but P95 3 and 4 mm respectively and breakthrough share 0 and 0,30 respectively.\n\n## External reference and boundary for transfer\n\n- [Varga 2020, Table4 MANDIBLE](https://doi.org/10.1111/clr.13578): apex mean +/- individual SD for freehand 2,30±1,02, pilot 1,95±1,28, fully guided 1,62±0,61 mm. Entry/angle is also used. Accepted manuscript has Table3 . [Wu 2020 , Figure4 ](https://doi.org/10.1186/s40729-020-00272-0): dynamic navigation apex 1,48 ± 0,65 mm in mixed jaw population. This is POPULATION - inputs ; segment-by-signatured tails are missing.\n- [Khaohoen 2024, Figure9](https://pmc.ncbi.nlm.nih.gov/articles/PMC10956322/): poolat apexmedel statiskt 1,44 mm [95 % KI 1,34–1,54], dynamiskt 1,36 [1,18–1,54]. Control of magnitude and source semantics. KI for agents does not become patient SD or P95.\n- [Jarnstedt 2022 , TableS2 / Results Reference segmentation]( https://doi.org/10.1038/s41598-022-20605-w : four experts SMCD against consensus, mean(SD ), 0,68 ( 0,38 ), 0,62 ( 0,39 ), 0,52 ( 0,38 ), 0,47 ( 0,40 ) mm . The table values of the main text are verified in XML ; direct supplement download failed on DNS . SMCD summarises the curve and does not identify local wall loss or its patient quintile.\n- [Gerlach 2010 , PMID20036043 ](https://pubmed.ncbi.nlm.nih.gov/20036043/): two independent reader in ten case; means of channel tracing-P95 1,3 mm , SD 0,384 , with forward deviations. Locator is abstract Results/Conclusions; full table missing here. 95 % of the channel points does not mean 95 % of patients or a local wall guarantee.\n- [IACAT2 § 4.1 , printed page 9 ]( https://federicobolelli.it/media/publications/pdfs/2023iciap_iacat2.pdf : six independent mask pairs provide medium-IoU 0,70 and Dice 0,81 . Their identity is not proven to our audit pairs, and the overlap measures cannot be converted to mm.\n\n17 numeric source entries are verified local . By six targeted selected sources, six can be used as inputs or context; **0 / 6** provides requested common segment matched physical 90 / 95 margin. Three lacks matched common tails; three measures another quantity / coverage unit. No residual against real channel on our poses is calculated. The search is not a systematic literature review. The sources confirmed the local restriction and did not change the design.\n\n## What does not holds and what the lab needs to measure\n\nThe guide profiles are random, not population elements with confidence limits. Mask revisions do not measure independent annotator errors or anatomical truth. Regional guide error, double-listed canal wall, verified mental/ramus landmarks and matched drill tracks are missing. The previous apex margin 2,62 – 3,45 mm in X31 had ≥ 1 mm remaining local apex margin, gamma distributed magnitude and isotrope direction. It is a different query than the entire cylinder error budget and cannot replace this table.\n\nMinimum common measurement is signed gap loss L=d(planned cylinder, CBCT mask) − d(achieved cylinder, independent adjudicated canal wall ), in the same registered case, guide and anatomically verified segment. It measures the correlation directly. A default maximum limit requires at least 29 and 59 independent samples per guide/segment for 90/95 % coverage with 95 % confidence during iid adoption (1 − p^n ≥ 0,95 ). It is a statistical minimum specification, no clinical trial recommendation. [FROZEN_PREDICTIONS.json ](FROZEN_PREDICTIONS.json) binds scenario predictions prior to such future measurement ; no new physical measurements was performed.\n\n## Loss, resolution and license\n\n2581 original virtual poses → 748 with close revision pairs: 1833 / 2581 missing ( 71,02%). The 748 poses held represent 741 image group+ FDI - sites , 149 dataset-ID but 148 exact image groups. 37 / 748 poses lack of segment, hence 16 / 330 heldout; no margin imputed. 0 identified independent wall pairs in the inherited census search of 440 multiartefact patients. X73 : s older source gate 43 changed/ 48 identical to published 40 / 51 preserved as FAIL ; we claim no new anatomic source review.\n\nEach connection goes via pose/wall witness, PER_TOOTH from PER_POINT , SIMULTANEOUS ; the consumer aggregates. PHENOMENOLOGICAL guide budgets are recorded as debt with the above measurement. No affinity sensitivity is reported; rigorous floating point enclosure is missing. The geometry is re-used with hash and interval data and has not been re-streamed in X87.\n\nToothFairy / ToothFairy2 : CC BY-SA 4.0 according to the source dataset license; here small derived digital mask dimensions are used. Maxillo's separate license must be verified for external distribution; local research only. Publications retain their respective copyright/licens. No Bits2Bites, Teeth3DS or mandible defect data are used. No personal data or clinical record fields are processed. The package is not published.\n\nControl line: equally informed scaler Cantelli inversion, rotated radius vector, separate ranking calculation and worm union interval subtraction consistent within frozen 1e-10 mm . Injections of +1 mm , SD error, source exchange, alia leak and false physical coverage status drop in [VALIDATION.json ](raw/VALIDATION.json) and raw source/round controls. A first control program had an additional factor 2 error; it was dropped and preserved in snapshots and R2_FAILURE_001.json. No threshold changed.\n\nStatus: PENDING_INDEPENDENT_REVIEW. Largest obstacles: matched independent anatomical and surgical measurement . Algorithm innovation and clinical applicability are not established.\n"
    unresolved = sum((s['segment'] not in SEGS for s in sites))
    resolved = len(sites) - unresolved
    readme = readme.replace('All 711 segment-bound poses', f'All {resolved} segmentbundna poser').replace('37/748 poser saknar segment', f'{unresolved}/748 poser saknar segment')
    readme = readme.replace('Published sample moments are treated as exact population moments: an unvalidated closure.', 'Published sampling moments are treated as precise population elements: an unvalidated assumption.')
    readme = readme.replace('Existing system-Python with NumPy/SciPy/Matplotlib is used via `python3 -s` to avoid a local NumPy/Matplotlib conflict. ', '')
    readme = readme.replace('R3 replaces the falsifiable regional Audit Quantile', 'The site-bound variant replaces the falsifiable regional revision quantile')
    readme = readme.replace(' A first control program had an additional factor 2 error; it was dropped and preserved in snapshots and R2_FAILURE_001.json. No threshold changed.', ' Failed gates and unchanged thresholds are preserved in raw data.')
    (R / 'README_DEMO.md').write_text(readme)
    tablehtml = '<table><thead><tr>' + ''.join(('<th>' + html.escape(x) + '</th>' for x in ['Guide', 'Segment', '90 % mm', '95 % mm', 'Changed/ 100 90 %', 'Changed/ 100 95 %', 'Physical coverage'])) + '</tr></thead><tbody>'
    for x in printable:
        tablehtml += '<tr>' + ''.join(('<td>' + html.escape(str(v)) + '</td>' for v in [x['guide'], x['segment'], fmt(x['budget90_mm']), fmt(x['budget95_mm']), fmt(x['changes90_per100'], 1), fmt(x['changes95_per100'], 1), 'UNKNOWN'])) + '</tr>'
    tablehtml += '</tbody></table>'
    (R / 'PRINT_TABLE.html').write_text('<!doctype html> <meta charset="utf-8"> <title> Nerve channel research budget </title> <style>body{font:15px sans-serif;max-width:1100px;margin:30px auto}table{border-collapse:collapse;width:100%}th,td{padding:9px;border:1px solid #bbb}h1{font-size:23px}img{width:100%}@media print{body{margin:0;font-size:11px}}</style> <h1> Guide × channel segment: conditional error budget </h1> <p> <b> Physical 90 / 95 %- coverage UNKNOWN . Research data, no clinical recommendation. </b> Pure error budget, residual target 0 mm. Mental proxy fails in both audit gates. Amen/ramus are not validated landmarks. </p>' + tablehtml + '<p> Shares refer to 181 mental and 127 molar locations among withheld image groups. The guide population module is adopted; local channel revision is not independent wall error. Positive digital separation requires a strict gap over the budget. A residual target c is added separately. See README_DEMO.md for assumptions , reference , failure and exact raw data . </p> <img src="figures/nerve_margin_table.png" alt="Model budgets and heldout revision coverage">')
    results = {'schema': 'X87-nerve-margin-table-v1', 'claim_type': 'information_link', 'review_state': 'PENDING_INDEPENDENT_REVIEW', 'outcome': 'REPRODUCIBLE_CONDITIONAL_TABLE_PHYSICAL_MARGIN_UNKNOWN', 'capability': 'Guide-by-segment 90/95% error-budget queries, explicit residual target, raw site decisions and per-pose release correction', 'physical_joint_coverage': 'UNKNOWN', 'clinical_recommendation': False, 'algorithm_novelty_claim': False, 'graph_registration': {'dispatch': 'BLOCKED_EXISTING_RESULT_HASH_MISMATCH', 'feedback': 'BLOCKED_NO_DISPATCH_RECEIPT', 'logs': ['raw/GRAPH_DISPATCH.stderr', 'raw/GRAPH_FEEDBACK.stderr'], 'canonical_graph_changed': False}, 'external_referent': {'kind': 'published_dataset', 'locator': str(R.parent / 'LANE_X73_CANAL_WALL_FULL/raw/LINEAGE_SITES.json'), 'compared_quantity': 'Digital public-mask-version whole-cylinder clearance and 2mm decision reversals; not true anatomical wall', 'refutes_us': True}, 'external_additional_referents': [external['external_referent'], {'kind': 'independent_measurement', 'locator': 'doi:10.1111/clr.13578 Table4; doi:10.1186/s40729-020-00272-0 Figure4', 'compared_quantity': 'Entry/apex/angular sample mean and individual SD', 'refutes_us': False}], 'rounds': [{k: v for (k, v) in r.items() if k in ['round', 'status', 'physical_gate', 'physical_margin', 'revision_validation', 'cost']} for r in [r1, r2, r3, r4]], 'main_table': r4['tables'], 'observed_revision_decisions': r1['local_census'], 'sufficiency': [r1['sufficiency'], val['site_summary_test']], 'measurement_debt': [{'quantity': 'Guide whole-cylinder loss tail by guide/segment', 'resolution': 'PHENOMENOLOGICAL', 'replacement': 'Registered plan/achieved signed gap loss on independent matched specimens'}, {'quantity': 'True local canal wall error', 'resolution': 'PER_POINT', 'replacement': 'Blind independent contour with adjudicated same-specimen physical reference'}, {'quantity': 'Mental/ramus segment landmarks', 'resolution': 'PER_SURFACE_REGION', 'replacement': 'Independent landmark annotation'}], 'edges': [{'source': 'X73 public mask union loss', 'target': 'DENT-GEOM-UNCERTAINTY / guide-canal margin consumer', 'quantity': 'clearance_loss', 'unit': 'mm', 'resolution': 'PER_TOOTH', 'source_raw_resolution': 'PER_POINT', 'time_scale': 'SIMULTANEOUS', 'status': 'PENDING_INDEPENDENT_REVIEW', 'physical_scope': 'digital release only'}], 'dropout': {'original_pose_rows': 2581, 'paired_pose_rows': 748, 'missing_pair': 1833, 'missing_pair_fraction': 1833 / 2581, 'unique_image_FDI_sites': 741, 'unresolved_segment_pose_rows': unresolved, 'resolved_segment_pose_rows': resolved, 'independent_wall_pairs': 0, 'source_candidate_rejections': external}, 'control_status': 'PASS_NUMERICAL_WITH_KNOWN_PHYSICAL_UNKNOWN', 'numerical_tolerance_mm': 1e-10, 'floating_point_enclosure': 'MISSING', 'affine_sensitivity_claim': False, 'failures_preserved': ['R1 physical identification fails', 'R2/R4 mental revision coverage fails at both targets', 'Posterior matched questions missing', 'raw/R2_FAILURE_001.json', 'Upstream X73 Maxillo40/51 mismatch', 'Supplement DOCX DNS failure'], 'cost': {'threads': 1, 'gpu': False, 'heavy_steps': False, 'r2': r2['cost'], 'r3': r3['cost'], 'r4': r4['cost'], 'report_seconds': time.perf_counter() - start, 'report_maxrss_kib': resource.getrusage(resource.RUSAGE_SELF).ru_maxrss, 'manual_preparation_discovery_validation_seconds': 'UNKNOWN', 'questions': 0, 'fallback': 'Physical measurement acquisition not performed', 'upstream_geometry_replay_cost_omitted': False, 'upstream_parent_known_geometry_seconds': 1618.73, 'source_geometry_reused_not_rerun': True}, 'array_storage': 'No new arrays >50MB; all own files below3GB cap', 'source_input_manifest_sha256': sha(R / 'INPUT_MANIFEST.json'), 'frozen_prediction_sha256': sha(R / 'FROZEN_PREDICTIONS.json'), 'next_construction': 'Independent same-specimen signed total gap-loss measurement, guide×landmark segment, locked predictions and order-statistic tolerance validation'}
    dump('results.json', results)
    (R / 'RESULTS.md').write_text('# Guide and local channel revision can now be asked at two coverage targets\n\nFour guide system × three segment/proxyer comes with a command, mm table, figure and per-pose decision. The real nerve channel 90 / 95 margin is UNKNOWN; external observations verify inputs and reveal incorrect magnitude transfers. Read [README_DEMO.md ](README_DEMO.md).\n\n' + '\n'.join(table) + "\n\nMentalproxy's two audit gates fails . Molar can withstand observed 95/97,5 percentage gates, with wide KI and without empirical guide/wall facits. The posterior branch has n=0. Site-bound mask union losses are controlled for all " + str(resolved) + ' segment-bound poses within 1e-10 mm; no rigorous floating point enclosure or physical coverage are claimed. Summary identity 0,0 hides 1 mm P95 difference and 50 percentage points of location.\n\nControl line: source values, scaler Cantelli, rotational vector, order statistics and per-poses subtraction match; injected errors fall. PENDING_INDEPENDENT_REVIEW.\n')
    handoff = "# X87 handoff\n\nRun `./run_all.sh` . Main product: README_DEMO.md , tables/NERVE_MARGIN_TABLE.csv , figures/nerve_margin_table.pdf , PRINT_TABLE.html . claim_type information_link . results.json and frozen PREREG_R1 / R2 / R3 / R4 bind the scope.\n\nR1 : physical margin is not identified. The exact same guide error and SD provide your own logical P95 3/4 mm and breakthrough share 0/0,30 ; identity error 0 . R2 : guide 95 + revision 95 for total 90 ; guide 97,5 + revision 97,5 for total 95 , residual 2 mm . Mental fulldout 49/54 and 52/54 fails respectively. Molar45/47 and 46/47 can handle observed gate, but KI and physical coverage limit. Posterior0/0.\n\nR3 : replace regional audit vantile with each existing pose's own targeted Union loss. control holds range within 1e-10 for all segment-bound poses, without future patient exchangeability. Median/range is never the decision limit of the site. The same multiset of losses linked differently to the same gap changes acceptance 50 percentage points with identity error 0 .\n\nR4 : separate the normal 0 from the desired remaining gap. Primary table uses c=0 ; R2 with c=2 is retained. This avoids confusion of extra residual targets with measured errors. All clinical margin response UNKNOWN . No new method or risk of nerve damage is calculated.\n\nExternal reference : VargaTable4 / WuFig4 inputs exactly matched; KhaohoenFig9 pooled means (not patient SD); JarnstedtTableS2 SMCD and GerlachPMID20036043 tracing-P95 (different operator/coverage unit); IACAT2 § 4.1 Dice/IoU (not mm). 0/6 targeted sources can identify common physical segment margin. Direct supplement download failed on DNS ; the main text TableS2 - values is available in XML . No new clinical/independent anatomical measurements. No source trees copied or large arrays created.\n\nNext essential construction: measure L=d(planned cylinder,CBCT mask) − d(achieved cylinder,adjudicated physical canal wall ) on the same registered specimen, with guide and expert certified landmarks. This trades unsigned guide moments + audit proxy for the actual joint consumer loss. FROZEN_PREDICTIONS.json is locked before such new measurement . At the default maximum limit, at least 29/59 independent specifics per stratum for 90/95 % coverage with 95 % confidence subiid. 348/708 such observation pairs for 12 stratum, without allegedly optimal experimental setup.\n\nEach detail edge is PER_TOOTH from PER_POINT and SIMULTANEOUS. Status PENDING_INDEPENDENT_REVIEW. GRAPH_FEEDBACK.json shall be recorded against DENT - GEOM - UNCERTAINTY ; any STALE_INPUT shall not be circumvented by graph change. No physical margin may be upgraded from these conditional budgets.\n"
    handoff += '\nGraphing actually executed: dispatch failed on ValueError : Results hash mismatching on existing feedback. Feedback failed then on missing tasks/graph_runs/X87-nerve-margin-table/DISPATCH.json . Exact stderr stored in raw. No native/generated graph was changed. Register the hashbound GRAPH_FEEDBACK base only after the graph owner solved the older mismatch.\n'
